Pi=m.pi;Tau=m.pi*2;Inf=m.huge;Sin=m.sin;Cos=m.cos;Tan=m.tan;Acos=m.acos;Asin=m.asin;Atan=m.atan;Sqrt=m.sqrt;function Vec(a,b,c)return{x=a,y=b,z=c}end;function Add(d,e)return{x=d.x+e.x,y=d.y+e.y,z=d.z+e.z}end;function Sub(d,e)return{x=d.x-e.x,y=d.y-e.y,z=d.z-e.z}end;function Scale(d,f)return{x=d.x*f,y=d.y*f,z=d.z*f}end;function Dot(d,e)return d.x*e.x+d.y*e.y+d.z*e.z end;function Cross(d,e)return{x=d.y*e.z-d.z*e.y,y=d.z*e.x-d.x*e.z,z=d.x*e.y-d.y*e.x}end;function Len(d)return Sqrt(d.x*d.x+d.y*d.y+d.z*d.z)end;function SetLen(d,f)return Scale(Norm(d),f)end;function Norm(d)return Len(d)~=0 and Scale(d,1/Len(d))or{x=0,y=0,z=0}end;function Lerp(d,e,g)return Add(d,Scale(Sub(e,d),g))end;function IJK(h,i,j)local k,l,m=Cos(h),Cos(i),Cos(j)local n,o,p=Sin(h),Sin(i),Sin(j)return Vec(Vec(l*m,l*p,-o),Vec(-k*p+n*o*m,k*m+n*o*p,n*l),Vec(k*o*m+n*p,k*o*p-n*m,k*l))end;function Local(d,q)return Vec(Dot(d,q.x),Dot(d,q.y),Dot(d,q.z))end;function Global(d,q)return Add(Scale(q.x,d.x),Add(Scale(q.y,d.y),Scale(q.z,d.z)))end;function Sphere(d)return Vec(Atan(d.x,d.y),Asin(d.z/Len(d)),Len(d))end;function Cartesian(d)return Vec(d.z*Cos(d.y)*Sin(d.x),d.z*Cos(d.y)*Cos(d.x),d.z*Sin(d.y))end;RADAR_TYPE=property.getNumber("Input Type")RADAR_PRIORITY=property.getNumber("Prioritise")TOLERANCE=property.getNumber("Tolerance")function onTick()has_target=false;guidance=Vec(0,0,0)if RADAR_TYPE==0 then guidance.x=input.getNumber(1)guidance.y=input.getNumber(2)if input.getNumber(1)~=0 or input.getNumber(2)~=0 then has_target=true end else GPS=Vec(input.getNumber(4),input.getNumber(8),input.getNumber(12))targets={}if input.getBool(1)==true then has_target=true;for r=1,8 do if input.getBool(r*4-3)then distance=input.getNumber(r*4-3)radarX=input.getNumber(r*4-2)radarY=input.getNumber(r*4-1)targets[r]=Vec(radarX,radarY,distance)last_locked=r end end;if RADAR_PRIORITY==0 then guidance=targets[1]elseif RADAR_PRIORITY==1 then lowest=Inf;candidate=Vec(0,0,0)for target in targets do deviation=Len(Sub(Cartesian(target),GPS))if deviation<lowest then candidate=target end end;guidance=candidate elseif RADAR_PRIORITY==2 then lowest=Inf;candidate=Vec(0,0,0)for target in targets do deviation=target.z;if deviation<lowest then candidate=target end end;guidance=candidate elseif RADAR_PRIORITY==3 then guidance=targets[last_locked]elseif RADAR_PRIORITY==4 then for r=#targets,1,-1 do target=targets[r]deviation=Len(Sub(Cartesian(target),GPS))if deviation<TOLERANCE then guidance=target end end end end end;output.setNumber(1,guidance.x)output.setNumber(2,guidance.y)output.setBool(1,has_target)end